@startuml

abstract class WorkProduct {
  + description : string
  + percentComplete : float
  + validate()
}

class Requirement extends WorkProduct {
  + validate()
  + publish()
}

class System extends WorkProduct {
  + validate()
  + deploy()
}

class Project {
  + startDate : date
  + endDate : date
}

class ProjectManager {
  + initiateProject()
  + terminateProject()
}

class Team {
  + description : string
}

ProjectManager "1" -- "*" Project : manage
ProjectManager "1" -- "*" Team : lead
Team "1..*" -- "1" Project : execute
Project "1" -- "*" Requirement : input
Project "1" -- "*" System : output

@enduml

